import json, re, random, chess, time
P = json.load(open("/tmp/obench-cell-ae_f49uo/bench_opencode_regex-chess_uwlf8an7/re.json"))
def run(fen):
    for p, r in P: fen = re.sub(p, r, fen)
    return fen.split("\n")
s = "<REDACTED_B64> w kq - 0 1"
exp = "<REDACTED_B64> b kq - 0 0\<REDACTED_B64> b kq - 0 0\<REDACTED_B64> b kq - 0 0"
