        print("FAIL", fen); print(sorted(ours)); print(sorted(ref)); raise SystemExit
random.seed(1); n = 0; t = time.time()
while n < 1500:
    b = chess.Board()
    for _ in range(random.randint(0, 150)):
        ms = list(b.legal_moves)
        if not ms: break
        b.push(random.choice(ms))
    if b.turn == chess.WHITE and not b.is_game_over():
        check(b.fen()); n += 1
print("ok", n, (time.time()-t)/n)
